<?php
$bbSize=bb_size('bb_history_size');$bbBase="SELECT b.*,u.name user_name FROM import_batches b LEFT JOIN users u ON u.id=b.user_id WHERE import_type='Beginning Balance'";
$bbTotal=(int)$pdo->query('SELECT COUNT(*) FROM ('.$bbBase.') bb_history')->fetchColumn();$bbOffset=min(max(0,(int)($_GET['bb_history_offset']??0)),max(0,(int)(ceil($bbTotal/$bbSize)-1)*$bbSize));
$bbRows=$pdo->query($bbBase.' ORDER BY b.id DESC LIMIT '.$bbSize.' OFFSET '.$bbOffset)->fetchAll();
echo '<div class="card bb-history"><div class="card-head"><div><h3>Beginning Balance Update History</h3><p class="muted small">Newest first · Upload and manual-entry records</p></div><span>'.$bbTotal.' records</span></div><div class="bb-history-scroll"><table class="table" data-server-paginated="1"><thead><tr><th>Date / Time</th><th>Source</th><th>Rows Read</th><th>Status</th><th>Updated By</th><th>Action</th></tr></thead><tbody>';
$bbFileIcon='<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8M8 17h8M12 13v4"/></svg>';
foreach($bbRows as $r){$manual=$r['filename']==='Manual entry';echo '<tr><td class="bb-number">'.e(substr($r['created_at'],0,10)).'<small>'.e(substr($r['created_at'],11)).'</small></td><td class="bb-source"><strong>'.($manual?'Manual entry':'Excel upload').'</strong><small>Record #'.(int)$r['id'].'</small>'.(!$manual?'<details class="bb-file-disclosure"><summary class="bb-file-trigger" data-bb-file data-filename="'.e($r['filename']).'" data-record="'.(int)$r['id'].'" data-uploaded="'.e($r['created_at']).'" data-extension="'.e(strtolower(pathinfo($r['filename'],PATHINFO_EXTENSION))).'">'.$bbFileIcon.'<span>View filename</span><span class="bb-file-expand" aria-hidden="true">↗</span></summary><div class="bb-file-fallback">'.e($r['filename']).'</div></details>':'').'</td><td class="bb-number">'.number_format((int)$r['rows_read']).'</td><td>'.badge(beginning_status_label($r['status']),status_badge_class($r['status'])).'</td><td>'.e($r['user_name']?:'—').'</td><td><a class="btn ghost sm" href="?page=import_detail&amp;id='.(int)$r['id'].'">View Details</a></td></tr>';}
if(!$bbRows)echo '<tr><td colspan="6">No beginning balance updates yet.</td></tr>';echo '</tbody></table></div>';
$bbParams=array_replace($_GET,['page'=>'beginning','bb_history_size'=>$bbSize]);unset($bbParams['history'],$bbParams['offset']);$bbPager=rs8_pagination($bbTotal,$bbOffset,$bbSize,$bbParams,'bb_history_offset');
$bbPager=str_replace('</span></div><div class="pagination-buttons">','</span>'.bb_size_label('bb_history_size',$bbSize).'</div><div class="pagination-buttons">',$bbPager);echo str_replace('aria-label="Table pages"','aria-label="Beginning history pages"',$bbPager).'</div>';

echo '<dialog id="bbFileDialog" class="bb-file-dialog" aria-labelledby="bbFileTitle" aria-describedby="bbFileName"><button type="button" class="bb-file-close" data-bb-file-close aria-label="Close filename">×</button><div class="bb-file-heading"><span class="bb-file-icon">'.$bbFileIcon.'</span><div><h3 id="bbFileTitle">Original filename</h3><p class="bb-file-record" data-bb-file-record></p></div></div><div class="bb-file-name" id="bbFileName"></div><div class="bb-file-meta"><span data-bb-file-type></span><span data-bb-file-date></span></div><div class="bb-file-actions"><button type="button" class="btn primary" data-bb-file-close>Close</button></div></dialog>';
